def format_message(message: str) -> str {
    msg_l = message.split(" ");
    new = [];
    for x in msg_l {
        if ("\n" in x) {
            x = x.replace("\n", "");
            new.append(x) if not (len(x) == 0) else None;
        } elif (len(x) != 0) {
            new.append(x);
        }
    }
    return " ".join(new);
}

